CREATE TABLE public.demo_gyvora_identity_keys (installation_id uuid NOT NULL, local_key text NOT NULL CHECK(length(local_key) BETWEEN 1 AND 300), kind text NOT NULL CHECK(kind IN ('G','C')), account_id uuid NOT NULL DEFAULT gen_random_uuid(), PRIMARY KEY(installation_id,kind,local_key), UNIQUE(account_id));
GRANT ALL ON public.demo_gyvora_identity_keys TO service_role;
ALTER TABLE public.demo_gyvora_identity_keys ENABLE ROW LEVEL SECURITY;
CREATE TRIGGER demo_identity_append_only BEFORE UPDATE OR DELETE ON public.demo_gyvora_identity_keys FOR EACH ROW EXECUTE FUNCTION public.protect_gyvora_registry();
CREATE TRIGGER demo_identity_no_truncate BEFORE TRUNCATE ON public.demo_gyvora_identity_keys FOR EACH STATEMENT EXECUTE FUNCTION public.protect_gyvora_registry();
CREATE FUNCTION public.reserve_demo_gyvora_ids(installation uuid, identities jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item jsonb; a uuid; result jsonb:='[]'::jsonb; k text; local_id text; code text; BEGIN IF jsonb_typeof(identities)<>'array' OR jsonb_array_length(identities)>200 THEN RAISE EXCEPTION 'Invalid identity batch'; END IF; FOR item IN SELECT value FROM jsonb_array_elements(identities) LOOP k:=item->>'kind'; local_id:=item->>'key'; IF k NOT IN ('G','C') OR local_id IS NULL OR length(local_id) NOT BETWEEN 1 AND 300 THEN RAISE EXCEPTION 'Invalid identity'; END IF; INSERT INTO public.demo_gyvora_identity_keys(installation_id,kind,local_key) VALUES(installation,k,local_id) ON CONFLICT DO NOTHING; SELECT account_id INTO a FROM public.demo_gyvora_identity_keys WHERE installation_id=installation AND kind=k AND local_key=local_id; code:=public.allocate_gyvora_id(k,a); result:=result || jsonb_build_array(jsonb_build_object('kind',k,'key',local_id,'id',code)); END LOOP; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.reserve_demo_gyvora_ids(uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.reserve_demo_gyvora_ids(uuid,jsonb) TO service_role;